const double RelZeroTolForIntensBorders = 0.005; //0.002; // To steer
const double RelZeroTolForFringeCount = 0.01; //0.5*RelZeroTolForIntensBorders; // To steer
long iFirst, iLast;
FindIntensityBorders1D(Sect1D, TreatExOrEz, RelZeroTolForIntensBorders, iFirst, iLast);

float *tE = ((TreatExOrEz == 'x')? Sect1D.pEx : Sect1D.pEz) + ((iFirst + 1) << 1);

char DerivSign = (*tE >= *(tE-2))? 1 : -1;
int PointsInFringe = 1;
long AmOfFringes = 0;

char E_IsZero = (*tE == 0.);
char LastFringeCounted = 0;

for(long i=iFirst + 2; i<=iLast; i++)
{
    tE += 2;

    double CurAbsE = ::fabs(*tE);
    double PrevAbsE = ::fabs(*(tE - 2));
    double MinAbsE = CurAbsE;
    if(PrevAbsE < MinAbsE) MinAbsE = PrevAbsE;
    double AbsTolE = RelZeroTolForFringeCount*MinAbsE;

    char NewE_IsZero = (*tE == 0.);
    if(!NewE_IsZero)
    {
        LastFringeCounted = 0;
        if(E_IsZero)
        {
            DerivSign = (*tE >= *(tE-2))? 1 : -1;
        }
        else
        {
 char NewDerivSign = (*tE >= *(tE-2))? 1 : -1; char NewDerivSign = (*tE >= (*(tE-2) + AbsTolE))? 1 : ((*tE < (*(tE-2) - AbsTolE))? -1 : 0); if(NewDerivSign == 0) NewDerivSign = DerivSign;

   double ePh = RadAccessData.eStart;
   double xRatMax = 1.E-23, zRatMax = 1.E-23, MaxPhaseChange = 1.E-23;
   for(int ie=0; ie<RadAccessData.ne; ie++)
   {
double Lambda_m = 1.239854e-06/ePh; double Lambda_m = 1.239842e-06/ePh; double xTetMagn = ::fabs((RadAccessData.nx - 1)*RadAccessData.xStep*Lambda_m); double zTetMagn = ::fabs((RadAccessData.nz - 1)*RadAccessData.zStep*Lambda_m); double PhaseChange = ::fabs((Pi/Lambda_m)*(RadAccessData.RobsX*xTetMagn*xTetMagn + RadAccessData.RobsZ*zTetMagn*zTetMagn));
